 pub fn terminal_work_binding(&self)->Option<semio_framework_value_control_contract::OriginalWorkBindingIdentity>{self.work_binding}
 /// 📒️ Observes whether the original ledger is present and has no bound allocation.
 pub fn terminal_ledger_available(&self)->bool{self.receipt.as_ref().is_some_and(|receipt|receipt.ledger.as_ref().is_some_and(|ledger|!ledger.is_bound()))}
 /// 🪪️ Checks the bound recipient against its original live owner.
 pub fn terminal_recipient_matches(&self,recipient:&NativeDecodeRetirementRecipient)->bool{self.recipient==Some(recipient.identity())}
 /// 🔒️ Observes the exact original terminal action retained by this frame.
 pub fn terminal_action_identity(&self)->Option<semio_framework_value_control_contract::OriginalConstructionActionIdentity>{self.terminal_lock}
 /// 🛂️ Checks the original recipient, ledger and Work before a fresh terminal action.
