 /// 🔗️ Restores the original lock from the two actual same-issuer retry owners.
 pub fn restore_terminal_retry(&mut self,recipient:&NativeDecodeRetirementRecipient,work:&super::OriginalWorkLoan<'_>,physical:&semio_framework_value_control_contract::OriginalConstructionLoan<'_>,witness:&semio_framework_value_native_outcome::OriginalReceivingRetryWitness<'_>)->Result<(),ValueError>{self.terminal_preflight(recipient,work,physical)?;if self.terminal_lock!=Some(witness.refusal_identity())||self.work_binding!=Some(witness.work_binding())||!witness.validates(physical)?{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"terminal retry changed its original owners"))}self.terminal_lock=Some(witness.original_identity());self.terminal_prior=None;Ok(())}
